begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('authenticated','public.accept_device_report(bytea,jsonb)','EXECUTE'),'parent cannot invoke device report RPC');
select ok(not has_function_privilege('anon','public.accept_device_report(bytea,jsonb)','EXECUTE'),'anonymous cannot report');
select ok(has_function_privilege('service_role','public.accept_device_report(bytea,jsonb)','EXECUTE'),'gateway report RPC available');
insert into auth.users(id) values('90000000-0000-4000-8000-000000000001');
insert into public.profiles(user_id) values('90000000-0000-4000-8000-000000000001');
insert into public.households(id,timezone_name,timezone_revision,deletion_state) values('90000000-0000-4000-8000-000000000002','Etc/UTC',1,'active');
insert into public.household_members values('90000000-0000-4000-8000-000000000002','90000000-0000-4000-8000-000000000001','owner',true);
insert into public.devices(id,household_id,nickname,platform,os_major,agent_version,policy_epoch) values('90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000002','fixture','android',16,'test','90000000-0000-4000-8000-000000000004');
insert into public.device_policies(device_id,household_id,version,policy_configured,daily_limit_seconds,manual_lock) values('90000000-0000-4000-8000-000000000003','90000000-0000-4000-8000-000000000002',0,false,null,false);
insert into private.device_credentials(credential_id,device_id,secret_digest,created_at,expires_at,generation) values(gen_random_uuid(),'90000000-0000-4000-8000-000000000003',decode(repeat('ab',32),'hex'),clock_timestamp(),clock_timestamp()+interval '90 days',1);
set local "request.jwt.claim.sub"='90000000-0000-4000-8000-000000000001';
select is(public.accept_control('90000000-0000-4000-8000-000000000010','90000000-0000-4000-8000-000000000003','SET_DAILY_LIMIT','{"daily_limit_seconds":3600}',0)->>'status','accepted','initial canonical limit');
select is(public.accept_control('90000000-0000-4000-8000-000000000011','90000000-0000-4000-8000-000000000003','LOCK','{}',1)->>'status','accepted','lock accepted');
select is((select status from public.operation_status where operation_id='90000000-0000-4000-8000-000000000011'),'pending','acceptance is pending before ACK');
create temp table fixture(report jsonb,response jsonb);
insert into fixture(report) select jsonb_build_object('protocol_version',1,'device_id','90000000-0000-4000-8000-000000000003','policy_epoch','90000000-0000-4000-8000-000000000004','applied_version',2,'report_sequence',1,'period_key','1:'||to_char(clock_timestamp() at time zone 'Etc/UTC','YYYY-MM-DD'),'used_ms',1000,'bonus_seconds',0,'remaining_ms',3599000,'manual_lock',true,'restriction_required',true,'restriction_applied',false,'health','ENFORCEMENT_UNAVAILABLE','accounting_status','NONE','observed_at',clock_timestamp());
update fixture set response=public.accept_device_report(decode(repeat('ab',32),'hex'),report);
select is((select response->>'code' from fixture),'ACKNOWLEDGED','report commits');
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report),response,'same sequence body preserves original receipt/freshness') from fixture;
select is((select status from public.operation_status where operation_id='90000000-0000-4000-8000-000000000011'),'persisted','no false applied');
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"used_ms":2000,"remaining_ms":3598000}')->>'code','REPORT_CONFLICT','sequence collision denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":0}')->>'code','REPORT_REJECTED','zero sequence denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"restriction_applied":true}')->>'code','REPORT_REJECTED','no enforcement adapter evidence accepted') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"remaining_ms":3600000}')->>'code','REPORT_REJECTED','impossible remaining denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"used_ms":0,"remaining_ms":3600000}')->>'code','REPORT_CONFLICT','same-period used rollback denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"applied_version":1}')->>'code','REPORT_CONFLICT','version rollback denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"manual_lock":false}')->>'code','REPORT_REJECTED','canonical lock cannot be forged') from fixture;
select is(public.accept_device_report(decode(repeat('cd',32),'hex'),report)->>'code','UNAUTHORIZED','unknown credential generic') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"policy_epoch":"90000000-0000-4000-8000-000000000099"}')->>'code','REPORT_REJECTED','foreign epoch denied') from fixture;
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report||'{"report_sequence":2,"health":null}')->>'code','REPORT_REJECTED','null health rejected') from fixture;
select is((select report_sequence from public.device_state where device_id='90000000-0000-4000-8000-000000000003'),1::bigint,'failed reports did not mutate latest state');
update private.device_credentials set revoked_at=clock_timestamp() where device_id='90000000-0000-4000-8000-000000000003';
select is(public.accept_device_report(decode(repeat('ab',32),'hex'),report)->>'code','UNAUTHORIZED','revoked cannot report') from fixture;
select throws_ok($$select public.parent_operation('90000000-0000-4000-8000-000000000019','90000000-0000-4000-8000-000000000003','UNLOCK','{}',0)$$,'PT409','VERSION_CONFLICT','HTTP wrapper translates only business conflict');
select ok(not has_function_privilege('anon','public.parent_operation(uuid,uuid,text,jsonb,bigint)','EXECUTE'),'no anonymous parent wrapper');
select * from finish();
rollback;
